import { useState, useEffect } from "react";
import api from "../../servicios/api";
import {
  crearEvaluacionPsico,
  actualizarEvaluacionPsico,
} from "../../servicios/evaluacionPsico";

// SUBDIMENSIÓN III: MOTRICIDAD Y CUIDADO DE SÍ MISMO
const ITEMS_MOTRICIDAD = [
  { id: 101, descripcion: "Se desplaza con coordinación y equilibrio." },
  { id: 102, descripcion: "Combina diferentes movimientos y posturas al desplazarse." },
  { id: 103, descripcion: "Corre con fluidez, variando velocidad, dirección y tipo de desplazamiento." },
  { id: 104, descripcion: "Mantiene la coordinación y control dinámico de su cuerpo en actividades motrices." },
  { id: 105, descripcion: "Ejecuta movimientos de manipulación que requieren control muscular fino." },
  { id: 106, descripcion: "Efectúa trabajos grafo-motores con precisión y seguridad." },
  { id: 107, descripcion: "Manipula objetos y herramientas con precisión." },
  { id: 108, descripcion: "Realiza ejercicios que requieren esfuerzo físico sostenido." },
  { id: 109, descripcion: "Realiza prácticas de autocuidado e higiene corporal en forma autónoma." },
  { id: 110, descripcion: "Cuida y guarda sus pertenencias (TDA)." },
  { id: 111, descripcion: "Manifiesta iniciativa en su cuidado y bienestar personal (TDA)." },
  { id: 112, descripcion: "Identifica situaciones u objetos riesgosos para su seguridad (TDA)." },
  { id: 113, descripcion: "Presenta automatismos o movimientos estereotipados (balanceo, manos, etc.)." },
];

// Escala del PDF
const ITEMS_COMUNICATIVAS = [
  { id: 1, descripcion: "Se comunica e interactúa con los demás de manera espontánea." },
  { id: 2, descripcion: "Se comunica e interactúa con los demás de manera guiada." },
  { id: 3, descripcion: "Participa en conversaciones con sus pares y/o adultos de forma espontánea." },
  { id: 4, descripcion: "La pronunciación, orden y estructura gramatical favorecen la comprensión del mensaje." },
  { id: 5, descripcion: "Utiliza oraciones completas en intervenciones orales/en lengua de señas." },
  { id: 6, descripcion: "Relata en forma secuenciada y clara experiencias personales." },
  { id: 7, descripcion: "Realiza y cumple instrucciones entregadas oralmente/en lengua de señas." },
  { id: 8, descripcion: "Ajusta su lenguaje a diversos contextos e interlocutores." },
  { id: 9, descripcion: "Su expresión oral/señada es coherente con su expresión facial/corporal." },
  { id: 10, descripcion: "Utiliza palabras, señas o conceptos especializados/rebuscados cuando corresponde." },
  { id: 11, descripcion: "Modula volumen y claridad de la voz/señalización según la situación." },
  { id: 12, descripcion: "Conoce y usa un vocabulario amplio." },
  { id: 13, descripcion: "Comunica sensaciones, emociones, necesidades e ideas a través del lenguaje." },
  { id: 14, descripcion: "Repite con frecuencia palabras/señas u oraciones (ecolalia)." },
];

const ITEMS_APRENDIZAJE = [
  { id: 1, descripcion: "Muestra preferencias e intereses diversos" },
  { id: 2, descripcion: "Se muestra activo e interesado por su entorno" },
  { id: 3, descripcion: "Se concentra en las actividades y acciones de la clase" },
  { id: 4, descripcion: "Mantiene atención sostenida al trabajar solo" },
  { id: 5, descripcion: "Mantiene atención sostenida al trabajar con otros" },
  { id: 6, descripcion: "Persiste en los trabajos y tareas hasta concluirlos" },
  { id: 7, descripcion: "Concluye los trabajos de forma ordenada. Es sistemático en la realización de su trabajo" },
  { id: 8, descripcion: "A partir de las instrucciones desarrolla su trabajo de manera autónoma" },
  { id: 9, descripcion: "Prefiere trabajar solo/a" },
  { id: 10, descripcion: "Trabaja mejor en colaboración con otros/as" },
  { id: 11, descripcion: "Le gusta resolver problemas" },
  { id: 12, descripcion: "Emprende con entusiasmo tareas nuevas" },
  { id: 13, descripcion: "Le gusta la experimentación" },
  { id: 14, descripcion: "Es competitivo/a" },
  { id: 15, descripcion: "Es creativo/a" },
];


function EvaluacionPsicoForm({ evaluacion, onSuccess }) {
  // Datos base
  const [formData, setFormData] = useState({
    estudiante: "",
    fecha: "",
    evaluador: "",
  });

  // Curso → Alumno
  const [cursoId, setCursoId] = useState("");
  const [cursos, setCursos] = useState([]);
  const [alumnos, setAlumnos] = useState([]);
  const [alumno, setAlumno] = useState(null);

  // IDENTIFICACIÓN / TRAYECTORIA / SITUACIÓN
  const [identificacion, setIdentificacion] = useState({
    observaciones_identificacion: "",
  });

  const [trayectoria, setTrayectoria] = useState({
    observaciones_trayectoria: "",
  });

  const [situacion, setSituacion] = useState({
    aspectos_destacados: "",
    observaciones_situacion: "",
  });

  // SUBDIMENSIÓN I
  const [valoresItems, setValoresItems] = useState(
    ITEMS_COMUNICATIVAS.reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  const [fortalezaArea, setFortalezaArea] = useState("");
  const [debilidadArea, setDebilidadArea] = useState("");
  const [sintesisArea, setSintesisArea] = useState("");
  const [observacionesArea, setObservacionesArea] = useState("");
  const [fortalezaMotricidad, setFortalezaMotricidad] = useState("");
  const [debilidadMotricidad, setDebilidadMotricidad] = useState("");
  const [sintesisMotricidad, setSintesisMotricidad] = useState("");
  const [observacionesMotricidad, setObservacionesMotricidad] = useState("");


  // Valores SUBDIMENSIÓN III
const [valoresMotricidad, setValoresMotricidad] = useState(
  ITEMS_MOTRICIDAD.reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
);

  // ===================================
  // Cargar cursos al iniciar
  // ===================================
  useEffect(() => {
    async function cargarCursos() {
      try {
        const res = await api.get("/cursos/");
        setCursos(res.data);
      } catch (err) {
        console.error("Error cargando cursos", err);
      }
    }
    cargarCursos();
  }, []);

  // ===================================
  // Si estamos editando: pre-cargar data
  // ===================================
  useEffect(() => {
    async function prefijar() {
      if (!evaluacion) return;

      setFormData({
        estudiante: evaluacion.estudiante || "",
        fecha: evaluacion.fecha || "",
        evaluador: evaluacion.evaluador || "",
      });

      // Cargar alumno y curso desde la evaluación (si viene el ID)
      if (evaluacion.estudiante) {
        try {
          const resEst = await api.get(`/estudiantes/${evaluacion.estudiante}/`);
          const est = resEst.data;
          setAlumno(est);

          if (est.curso?.id) {
            setCursoId(est.curso.id);
            await cargarAlumnosPorCurso(est.curso.id);
          }
        } catch (err) {
          console.error("Error cargando alumno de evaluación", err);
        }
      }
      // NOTA: Como guardamos todo en 'observaciones' como texto, no separamos de vuelta en estos campos.
    }
    prefijar();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [evaluacion]);

  // ===================================
  // Helpers para cargar alumnos
  // ===================================
  const cargarAlumnosPorCurso = async (idCurso) => {
    if (!idCurso) {
      setAlumnos([]);
      setAlumno(null);
      setFormData((prev) => ({ ...prev, estudiante: "" }));
      return;
    }
    try {
      const res = await api.get(`/estudiantes/?curso=${idCurso}`);
      setAlumnos(res.data);
    } catch (err) {
      console.error("Error cargando alumnos", err);
    }
  };

  const cargarAlumno = async (idEstudiante) => {
    if (!idEstudiante) {
      setAlumno(null);
      return;
    }
    try {
      const res = await api.get(`/estudiantes/${idEstudiante}/`);
      setAlumno(res.data);
    } catch (err) {
      console.error("Error cargando ficha del alumno", err);
    }
  };

  // ===================================
  // Handlers
  // ===================================
  const handleCursoChange = async (e) => {
    const id = e.target.value;
    setCursoId(id);
    await cargarAlumnosPorCurso(id);
  };

  const handleAlumnoChange = (e) => {
    const id = e.target.value;
    setFormData((prev) => ({ ...prev, estudiante: id }));
    cargarAlumno(id);
  };

  const handleChangeBase = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleChangeIdentificacion = (e) => {
    const { name, value } = e.target;
    setIdentificacion((prev) => ({ ...prev, [name]: value }));
  };

  const handleChangeTrayectoria = (e) => {
    const { name, value } = e.target;
    setTrayectoria((prev) => ({ ...prev, [name]: value }));
  };

  const handleChangeSituacion = (e) => {
    const { name, value } = e.target;
    setSituacion((prev) => ({ ...prev, [name]: value }));
  };

  const handleRadioChange = (itemId, valor) => {
    setValoresItems((prev) => ({ ...prev, [itemId]: valor }));
  };

  // ===================================
  // Submit
  // ===================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    const textoObservacionesCompuesto = `
[IDENTIFICACIÓN DEL ESTUDIANTE]
${identificacion.observaciones_identificacion || "-"}

[TRAYECTORIA ESCOLAR]
${trayectoria.observaciones_trayectoria || "-"}

[SITUACIÓN ESCOLAR ACTUAL]
Aspectos destacados:
${situacion.aspectos_destacados || "-"}

Otras observaciones:
${situacion.observaciones_situacion || "-"}

[I. HABILIDADES COMUNICATIVAS]
${ITEMS_COMUNICATIVAS.map(
  (item) => ` ${item.id}. ${item.descripcion} => ${valoresItems[item.id]}`
).join("\n")}

Fortaleza: ${fortalezaArea || "-"}
Debilidad: ${debilidadArea || "-"}
Síntesis: ${sintesisArea || "-"}
Observaciones adicionales: ${observacionesArea || "-"}
    `.trim();

    const payload = {
      estudiante: formData.estudiante,
      fecha: formData.fecha,
      evaluador: formData.evaluador,
      observaciones: textoObservacionesCompuesto,
    };

    try {
      if (evaluacion?.id) {
        await actualizarEvaluacionPsico(evaluacion.id, payload);
      } else {
        await crearEvaluacionPsico(payload);
      }
      alert("✔ Evaluación guardada correctamente");
      onSuccess?.();
    } catch (err) {
      console.error(err);
      alert("❌ Error al guardar la evaluación");
    }
  };

  // SUBDIMENSIÓN II – HABILIDADES SOCIALES Y AFECTIVIDAD
const [subdimensiones, setSubdimensiones] = useState({
  comunicativas: {},     // subdimensión I
  sociales: {},          // subdimensión II
  fortaleza_area: "",
  debilidad_area: "",
  sintesis_area: "",
  observaciones_area: "",
  fortaleza_social: "",
  debilidad_social: "",
  sintesis_social: "",
  obs_social: "",
});


  // ===================================
  // RENDER
  // ===================================
  return (
    <form onSubmit={handleSubmit} className="bg-light p-3 border rounded">

      {/* CURSO + ALUMNO */}
      <div className="row mb-3">
        <div className="col-md-6">
          <label className="form-label">Curso</label>
          <select
            className="form-select"
            value={cursoId}
            onChange={handleCursoChange}
          >
            <option value="">Seleccionar curso...</option>
            {cursos.map((c) => (
              <option key={c.id} value={c.id}>
                {c.nombre} {c.anio_escolar ? `(${c.anio_escolar})` : ""}
              </option>
            ))}
          </select>
        </div>

        <div className="col-md-6">
          <label className="form-label">Alumno</label>
          <select
            className="form-select"
            name="estudiante"
            value={formData.estudiante}
            onChange={handleAlumnoChange}
            disabled={!cursoId}
            required
          >
            <option value="">
              {cursoId ? "Seleccionar alumno..." : "Seleccione curso primero"}
            </option>
            {alumnos.map((a) => (
              <option key={a.id} value={a.id}>
                {a.nombres_apellidos} — {a.run || ""}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* FICHA DEL ALUMNO */}
      {alumno && (
        <div className="alert alert-secondary">
          <h5 className="mb-2">Ficha del estudiante</h5>
          <p><b>Nombre:</b> {alumno.nombres_apellidos}</p>
          <p><b>RUN:</b> {alumno.run || "—"}</p>
          <p><b>Curso:</b> {alumno.curso?.nombre || "—"}</p>
          <p><b>Género:</b> {alumno.genero || "—"}</p>
          <p><b>Fecha nacimiento:</b> {alumno.fecha_nacimiento || "—"}</p>
          <p><b>Apoderado:</b> {alumno.apoderado?.nombres_apellidos || "—"}</p>
        </div>
      )}

      {/* EVALUADOR + FECHA */}
      <div className="row mb-3 mt-3">
        <div className="col-md-6">
          <label className="form-label">Evaluador</label>
          <input
            className="form-control"
            name="evaluador"
            value={formData.evaluador}
            onChange={handleChangeBase}
            required
          />
        </div>
        <div className="col-md-6">
          <label className="form-label">Fecha</label>
          <input
            type="date"
            className="form-control"
            name="fecha"
            value={formData.fecha}
            onChange={handleChangeBase}
          />
        </div>
      </div>

      {/* IDENTIFICACIÓN */}
      <h5 className="mt-4">Identificación del estudiante</h5>
      <div className="mb-3">
        <label className="form-label">Observaciones de identificación</label>
        <textarea
          className="form-control"
          rows={2}
          name="observaciones_identificacion"
          value={identificacion.observaciones_identificacion}
          onChange={handleChangeIdentificacion}
          placeholder="Lengua materna, lengua de uso, vía de comunicación, escolaridad alcanzada, etc."
        />
      </div>

      {/* ---------------- TRAYECTORIA ESCOLAR ---------------- */}
<h5 className="mt-4">Trayectoria Escolar</h5>
<div className="row">

  {/* Edad de ingreso */}
  <div className="col-md-4 mb-3">
    <label className="form-label">Edad de ingreso al sistema escolar</label>
    <input
      type="number"
      className="form-control"
      name="edad_ingreso"
      value={trayectoria.edad_ingreso || ""}
      onChange={handleChangeTrayectoria}
      placeholder="Ej: 5"
    />
  </div>

  {/* Asistió a jardín infantil */}
  <div className="col-md-4 mb-3">
    <label className="form-label d-block">Asistió a jardín infantil</label>
    <select
      className="form-select"
      name="jardin"
      value={trayectoria.jardin || ""}
      onChange={handleChangeTrayectoria}
    >
      <option value="">Seleccione...</option>
      <option value="si">Sí</option>
      <option value="no">No</option>
    </select>
  </div>

  {/* Ha repetido cursos */}
  <div className="col-md-4 mb-3">
    <label className="form-label d-block">Ha repetido curso(s)</label>
    <select
      className="form-select"
      name="repitencia"
      value={trayectoria.repitencia || ""}
      onChange={handleChangeTrayectoria}
    >
      <option value="">Seleccione...</option>
      <option value="si">Sí</option>
      <option value="no">No</option>
    </select>
    {trayectoria.repitencia === "si" && (
      <input
        className="form-control mt-2"
        name="cursos_repetidos"
        value={trayectoria.cursos_repetidos || ""}
        onChange={handleChangeTrayectoria}
        placeholder="¿Qué curso(s)?"
      />
    )}
  </div>

  {/* Nº de colegios */}
  <div className="col-md-4 mb-3">
    <label className="form-label">Nº de colegios en que ha estudiado</label>
    <input
      type="number"
      className="form-control"
      name="colegios"
      value={trayectoria.colegios || ""}
      onChange={handleChangeTrayectoria}
    />
  </div>

  {/* Modalidad de enseñanza */}
  <div className="col-md-8 mb-3">
    <label className="form-label d-block">Modalidad de enseñanza</label>

    <div className="form-check form-check-inline">
      <input
        className="form-check-input"
        type="checkbox"
        name="modalidad_regular"
        checked={trayectoria.modalidad_regular || false}
        onChange={(e) =>
          setTrayectoria((prev) => ({
            ...prev,
            modalidad_regular: e.target.checked,
          }))
        }
      />
      <label className="form-check-label">Regular</label>
    </div>

    <div className="form-check form-check-inline">
      <input
        className="form-check-input"
        type="checkbox"
        name="modalidad_especial"
        checked={trayectoria.modalidad_especial || false}
        onChange={(e) =>
          setTrayectoria((prev) => ({
            ...prev,
            modalidad_especial: e.target.checked,
          }))
        }
      />
      <label className="form-check-label">Especial</label>
    </div>

    <div className="form-check form-check-inline">
      <input
        className="form-check-input"
        type="checkbox"
        name="modalidad_tecnica"
        checked={trayectoria.modalidad_tecnica || false}
        onChange={(e) =>
          setTrayectoria((prev) => ({
            ...prev,
            modalidad_tecnica: e.target.checked,
          }))
        }
      />
      <label className="form-check-label">Técnica</label>
    </div>
  </div>

  {/* Tiene amigos */}
  <div className="col-md-4 mb-3">
    <label className="form-label d-block">Tiene / tuvo amigos(as)</label>
    <select
      className="form-select"
      name="amigos"
      value={trayectoria.amigos || ""}
      onChange={handleChangeTrayectoria}
    >
      <option value="">Seleccione...</option>
      <option value="si">Sí</option>
      <option value="no">No</option>
    </select>
  </div>

  {/* Motivo de los cambios */}
  <div className="col-12 mb-3">
    <label className="form-label">Motivo de los cambios</label>
    <textarea
      className="form-control"
      name="motivo_cambios"
      rows={2}
      value={trayectoria.motivo_cambios || ""}
      onChange={handleChangeTrayectoria}
      placeholder="Ej: Cambios de domicilio, problemas de convivencia, traslado laboral, etc."
    />
  </div>
</div>


      {/* SITUACIÓN ACTUAL */}
     {/* ---------------- SITUACIÓN ESCOLAR ACTUAL ---------------- */}
<h5 className="mt-4">Situación escolar actual</h5>

<div className="row">

  {/* Nivel / curso actual */}
  <div className="col-md-6 mb-3">
    <label className="form-label">Nivel / curso actual</label>
    <input
      className="form-control"
      name="nivel_actual"
      value={situacion.nivel_actual || ""}
      onChange={handleChangeSituacion}
      placeholder="Ej: 4° Básico"
    />
  </div>

  {/* Asiste regularmente */}
  <div className="col-md-6 mb-3">
    <label className="form-label d-block">Asiste regularmente</label>
    <select
      className="form-select"
      name="asiste_regular"
      value={situacion.asiste_regular || ""}
      onChange={handleChangeSituacion}
    >
      <option value="">Seleccione...</option>
      <option value="si">Sí</option>
      <option value="no">No</option>
    </select>
  </div>

  {/* Asiste con agrado */}
  <div className="col-md-6 mb-3">
    <label className="form-label d-block">Asiste con agrado</label>
    <select
      className="form-select"
      name="asiste_agrado"
      value={situacion.asiste_agrado || ""}
      onChange={handleChangeSituacion}
    >
      <option value="">Seleccione...</option>
      <option value="si">Sí</option>
      <option value="no">No</option>
    </select>
  </div>

  {/* Apoyo familiar en tareas */}
  <div className="col-md-6 mb-3">
    <label className="form-label d-block">Apoyo familiar en tareas</label>
    <select
      className="form-select"
      name="apoyo_familiar"
      value={situacion.apoyo_familiar || ""}
      onChange={handleChangeSituacion}
    >
      <option value="">Seleccione...</option>
      <option value="si">Sí</option>
      <option value="no">No</option>
    </select>
  </div>

  {/* Aspectos destacados */}
  <div className="col-12 mb-3">
    <label className="form-label">
      Aspectos destacados en su historia educativa
      <span className="text-muted"> (conducta, rendimiento, participación, relaciones sociales…)</span>
    </label>
    <textarea
      className="form-control"
      name="aspectos_destacados"
      rows={2}
      value={situacion.aspectos_destacados || ""}
      onChange={handleChangeSituacion}
    />
  </div>

          {/* Observaciones adicionales */}
          <div className="col-12 mb-3">
            <label className="form-label">Observaciones</label>
            <textarea
              className="form-control"
              name="observaciones_situacion"
              rows={2}
              value={situacion.observaciones_situacion || ""}
              onChange={handleChangeSituacion}
            />
          </div>

        </div>


              {/* SUBDIMENSIÓN I */}
              <h5 className="mt-4">I. Habilidades comunicativas</h5>
              <p className="text-muted">
                S=Siempre (1), G=Generalmente (2), O=Ocasionalmente (3),
                N=Nunca (4), N/O=No observado (0).
              </p>

              <table className="table table-bordered align-middle">
                <thead className="table-secondary text-center">
                  <tr>
                    <th style={{ width: "60%" }}>Ítem</th>
                    <th>S<br />1</th>
                    <th>G<br />2</th>
                    <th>O<br />3</th>
                    <th>N<br />4</th>
                    <th>N/O<br />0</th>
                  </tr>
                </thead>
                <tbody>
                  {ITEMS_COMUNICATIVAS.map((item) => (
                    <tr key={item.id}>
                      <td>{item.descripcion}</td>
                      {[1, 2, 3, 4, 0].map((valor) => (
                        <td className="text-center" key={valor}>
                          <input
                            type="radio"
                            name={`item-${item.id}`}
                            checked={valoresItems[item.id] === valor}
                            onChange={() => handleRadioChange(item.id, valor)}
                          />
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>

              {/* FORTALEZA / DEBILIDAD / SÍNTESIS / OBSERVACIONES ÁREA */}
              <div className="mb-3">
                <label className="form-label">
                  Mayor <strong>fortaleza</strong> en esta área
                </label>
                <textarea
                  className="form-control"
                  rows={2}
                  value={fortalezaArea}
                  onChange={(e) => setFortalezaArea(e.target.value)}
                />
              </div>
              <div className="mb-3">
                <label className="form-label">
                  Mayor <strong>debilidad</strong> en esta área
                </label>
                <textarea
                  className="form-control"
                  rows={2}
                  value={debilidadArea}
                  onChange={(e) => setDebilidadArea(e.target.value)}
                />
              </div>
              <div className="mb-3">
                <label className="form-label">
                  <strong>Síntesis</strong> del desempeño general
                </label>
                <textarea
                  className="form-control"
                  rows={2}
                  value={sintesisArea}
                  onChange={(e) => setSintesisArea(e.target.value)}
                />
              </div>
              <div className="mb-3">
                <label className="form-label">
                  Observaciones adicionales del área
                </label>
                <textarea
                  className="form-control"
                  rows={2}
                  value={observacionesArea}
                  onChange={(e) => setObservacionesArea(e.target.value)}
                />
              </div>
                  {/* ---------------- SUBDIMENSIÓN II: HABILIDADES SOCIALES Y AFECTIVIDAD ---------------- */}
        <h5 className="mt-5">II. Habilidades sociales y afectividad</h5>
        <p className="text-muted">
          Marque según el significado: S=Siempre (1), G=Generalmente (2), O=Ocasionalmente (3),
          N=Nunca (4), N/O=No observado (0).
        </p>

        <table className="table table-bordered align-middle">
          <thead className="table-secondary text-center">
            <tr>
              <th style={{ width: "60%" }}>Ítem</th>
              <th>S<br />1</th>
              <th>G<br />2</th>
              <th>O<br />3</th>
              <th>N<br />4</th>
              <th>N/O<br />0</th>
            </tr>
          </thead>

          <tbody>
            {[
              "Expresa verbal y/o corporalmente distintas emociones y sentimientos.",
              "Comparte con sus compañeros trabajo y/o actividades recreativas.",
              "Se relaciona afectivamente con los adultos de su medio.",
              "Se expresa con seguridad y confianza.",
              "Expresa sus sentimientos y emociones de acuerdo a la situación y contexto.",
              "Espera su turno en actividades grupales.",
              "Distingue los comportamientos que pueden producir consecuencias positivas o negativas.",
              "Expresa y reconoce distintas emociones y sentimientos en sí mismo y en los otros.",
              "Ajusta su actividad motriz a las exigencias del contexto y situación.",
              "Ante una dificultad o impedimento busca alternativas de solución.",
              "Inicia actividades de trabajo y/o recreativas.",
              "Utiliza diversos recursos para comunicarse o interactuar con su medio.",
              "Se muestra activo e interesado por su entorno.",
              "Solicita ayuda cuando la requiere.",
              "Acepta críticas y aportes en sus trabajos."
            ].map((texto, index) => {
              const id = index + 1;
              return (
                <tr key={id}>
                  <td>{id}. {texto}</td>

                  {[1, 2, 3, 4, 0].map((valor) => (
                    <td className="text-center" key={valor}>
                      <input
                        type="radio"
                        name={`social-${id}`}
                        checked={(subdimensiones.sociales || {})[id] === valor}
                        onChange={() =>
                          setSubdimensiones((prev) => ({
                            ...prev,
                            sociales: {
                              ...(prev.sociales || {}),
                              [id]: valor,
                            },
                          }))
                        }
                      />
                    </td>
                  ))}
                </tr>
              );
            })}
          </tbody>
        </table>

        {/* Fortalezas, Debilidades, Síntesis, Observaciones */}
        <div className="mb-3">
          <label className="form-label">
            Describa la mayor <strong>fortaleza</strong> del estudiante en esta área
          </label>
          <textarea
            className="form-control"
            rows={2}
            value={subdimensiones.fortaleza_social || ""}
            onChange={(e) =>
              setSubdimensiones((prev) => ({
                ...prev,
                fortaleza_social: e.target.value,
              }))
            }
          />
        </div>

        <div className="mb-3">
          <label className="form-label">
            Describa la mayor <strong>debilidad</strong> del estudiante en esta área
          </label>
          <textarea
            className="form-control"
            rows={2}
            value={subdimensiones.debilidad_social || ""}
            onChange={(e) =>
              setSubdimensiones((prev) => ({
                ...prev,
                debilidad_social: e.target.value,
              }))
            }
          />
        </div>

        <div className="mb-3">
          <label className="form-label">
            <strong>Síntesis</strong>: desempeño general del estudiante en esta área
          </label>
          <textarea
            className="form-control"
            rows={2}
            value={subdimensiones.sintesis_social || ""}
            onChange={(e) =>
              setSubdimensiones((prev) => ({
                ...prev,
                sintesis_social: e.target.value,
              }))
            }
          />
        </div>

        <div className="mb-3">
          <label className="form-label">
            Observaciones adicionales del área (aspectos no considerados anteriormente)
          </label>
          <textarea
            className="form-control"
            rows={2}
            value={subdimensiones.obs_social || ""}
            onChange={(e) =>
              setSubdimensiones((prev) => ({
                ...prev,
                obs_social: e.target.value,
              }))
            }
          />
        </div>
    {/* ========================================================= */}
{/*   III. MOTRICIDAD Y CUIDADO DE SÍ MISMO                  */}
{/* ========================================================= */}

<h5 className="mt-4">III. Motricidad y Cuidado de Sí Mismo</h5>
<p className="text-muted">
  (S=Siempre (1), G=Generalmente (2), O=Ocasionalmente (3), N=Nunca (4), N/O=No observado (0))
</p>

<table className="table table-bordered align-middle">
  <thead className="table-secondary text-center">
    <tr>
      <th style={{ width: "60%" }}>Ítem</th>
      <th>S<br />1</th>
      <th>G<br />2</th>
      <th>O<br />3</th>
      <th>N<br />4</th>
      <th>N/O<br />0</th>
    </tr>
  </thead>

  <tbody>
    {ITEMS_MOTRICIDAD.map((item) => (
      <tr key={item.id}>
        <td>{item.descripcion}</td>

        {[1, 2, 3, 4, 0].map((valor) => (
          <td className="text-center" key={valor}>
            <input
              type="radio"
              name={`motricidad-${item.id}`}
              checked={valoresMotricidad[item.id] === valor}
              onChange={() =>
                setValoresMotricidad((prev) => ({
                  ...prev,
                  [item.id]: valor,
                }))
              }
            />
          </td>
        ))}
      </tr>
    ))}
  </tbody>
</table>

{/* CAMPOS DE TEXTO */}
<div className="mb-3">
  <label className="form-label">
    Describa la mayor <strong>fortaleza</strong> del estudiante en esta área
  </label>
  <textarea
    className="form-control"
    rows={2}
    value={fortalezaMotricidad}
    onChange={(e) => setFortalezaMotricidad(e.target.value)}
  />
</div>

<div className="mb-3">
  <label className="form-label">
    Describa la mayor <strong>debilidad</strong> del estudiante en esta área
  </label>
  <textarea
    className="form-control"
    rows={2}
    value={debilidadMotricidad}
    onChange={(e) => setDebilidadMotricidad(e.target.value)}
  />
</div>

<div className="mb-3">
  <label className="form-label"><strong>Síntesis</strong></label>
  <textarea
    className="form-control"
    rows={2}
    value={sintesisMotricidad}
    onChange={(e) => setSintesisMotricidad(e.target.value)}
  />
</div>

<div className="mb-3">
  <label className="form-label">
    Observaciones adicionales del área
  </label>
  <textarea
    className="form-control"
    rows={2}
    value={observacionesMotricidad}
    onChange={(e) => setObservacionesMotricidad(e.target.value)}
  />
</div>



      <button type="submit" className="btn btn-success w-100 mt-3">
        {evaluacion ? "Actualizar evaluación" : "Crear evaluación"}
      </button>
    </form>
  );
}

export default EvaluacionPsicoForm;
